mapper.sql:
FROM store s
WHERE s.shelf_status = #{shelfStatus}

    AND s.region_id IN

        #{regionId}



    AND EXISTS (
        SELECT 1
        FROM store_tag_rel rel
        INNER JOIN tag t ON t.id = rel.tag_id
        WHERE rel.store_id = s.id
          AND t.code = #{tagCode}
          AND t.enabled = TRUE
    )


    AND s.price_from >= #{priceMin}


    AND s.price_from <= #{priceMax}

mapper.select:
SELECT s.*

ORDER BY ${orderBy}
LIMIT #{limit} OFFSET #{offset}
